contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");

        c.addToBalance{value: depositAmount}(); if (__ESBMC_reverted()) return;

        uint recordedAfterDeposit = c.getBalance(address(this)); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint recordedAfterWithdraw = c.getBalance(address(this)); if (__ESBMC_reverted()) return;

        assert(reverted ? recordedAfterWithdraw == recordedAfterDeposit : recordedAfterWithdraw == 0);
    }

    receive() external payable {}
}

